 private void currentIfNeeded(int ticket)throws IOException{if(ticket>=0)current(ticket);}
 synchronized JSONArray games()throws Exception{return installed().getJSONArray("games");}
 synchronized String version()throws Exception{return installed().optString("version","");}
 synchronized String state()throws Exception{JSONObject s=installed();return new JSONObject().put("version",s.optString("version","")).put("addedHashes",s.optJSONArray("addedHashes")).toString();}
 synchronized File resolve(String hash)throws Exception{if(!hash.matches("[a-f0-9]{64}"))throw new IOException("游戏身份无效");JSONObject data=installed();for(String key:new String[]{"files","retained"}){JSONArray all=data.optJSONArray(key);if(all!=null)for(int i=all.length()-1;i>=0;i--){JSONObject f=all.getJSONObject(i);if(hash.equals(f.getString("sha256")))return ref(f).file;}}return null;}
 synchronized String verifyInstalled()throws Exception{JSONObject data=installed();for(String key:new String[]{"files","retained"}){JSONArray list=data.optJSONArray(key);if(list==null)continue;for(int i=0;i<list.length();i++){JSONObject f=list.getJSONObject(i);if(!valid(ref(f),f,-1))return JSONObject.quote("资源缺失或损坏："+f.getString("path"));}}return "null";}
 synchronized String presence(String json)throws Exception{JSONArray list=new JSONArray(json);JSONObject result=new JSONObject();for(int i=0;i<list.length();i++){JSONObject g=list.getJSONObject(i);String hash=g.getString("hash"),path=g.getString("path");File f=resolve(hash);boolean yes=f!=null&&f.isFile()&&f.length()==g.getLong("bytes");if(f==null&&context!=null&&safe(path)){if(g.optString("system","nes").equals("nes"))try(InputStream in=context.getAssets().open(path)){yes=true;}catch(IOException ignored){}else{f=new File(filesDir,path);yes=f.isFile()&&f.length()==g.getLong("bytes");}}result.put(hash,yes);}return result.toString();}
 static String dependencyError(JSONObject game,File main)throws Exception{if(game.has("bios")&&!game.isNull("bios")&&!game.optString("bios").isEmpty()){String name=game.getString("bios");if(main==null||!safe(name)||name.contains("/"))return "BIOS路径无效";File f=new File(main.getParentFile(),name);if(!f.isFile())return "缺少BIOS："+name;if(!HallUpdates.fileDigest(f).equals(game.optString("biosHash")))return "BIOS校验失败："+name;}return null;}
 synchronized String status(){return status;}
 private synchronized void publish(int ticket,String phase,String label,long done,long total)throws Exception{if(ticket!=generation)return;JSONObject v=new JSONObject().put("phase",phase).put("label",label).put("canCancel",!phase.equals("committing"));if(total>0)v.put("bytesDone",done).put("bytesTotal",total).put("percent",Math.min(100,done*100/total));status=v.toString();}
 synchronized void downloading(long bytes,long total){try{publish(generation,"downloading","正在下载资源包："+bytes/1048576+" MB",bytes,total);}catch(Exception ignored){}}
 synchronized void fail(String message){try{status=new JSONObject().put("phase","failed").put("error",message==null?"资源读取失败":message).toString();}catch(Exception ignored){}}
 synchronized void waiting(){cancel();try{publish(generation,"choosing","请选择完整资源ZIP",0,0);}catch(Exception ignored){}}
 synchronized void cancel(){generation++;Plan p=prepared;prepared=null;if(p!=null&&p.owned)p.zip.delete();status="{\"phase\":\"cancelled\",\"label\":\"已取消，原有游戏和存档保留\"}";}
 private synchronized int begin(){cancel();return generation;}
 void prepare(final Uri uri){final int ticket=begin();try{publish(ticket,"checking","正在读取资源包清单…",0,0);}catch(Exception ignored){}new Thread(new Runnable(){public void run(){Plan p=null;try{p=inspect(uri,ticket);ready(p);}catch(Exception e){synchronized(HallResources.this){if(ticket==generation)fail(explain(e));}if(p!=null&&p.owned)p.zip.delete();}}},"pack-review").start();}
 String prepareFileForCheck(File zip){int ticket=begin();try{Plan p=inspectFile(zip,false,ticket);ready(p);}catch(Exception e){fail(explain(e));}return status;}
 private Plan inspect(Uri uri,int ticket)throws Exception{
  if(uri!=null&&"file".equals(uri.getScheme())){File f=new File(uri.getPath());boolean owned=f.getCanonicalPath().startsWith(cache.getCanonicalPath()+File.separator);try{return inspectFile(f,owned,ticket);}catch(Exception e){if(owned)f.delete();throw e;}}
  if(context==null||uri==null)throw new IOException("源文件不可读取");long size=-1;try(Cursor cursor=context.getContentResolver().query(uri,new String[]{OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()&&!cursor.isNull(0))size=cursor.getLong(0);}catch(Exception ignored){}
  if(size>MAX_ZIP)throw new IOException("资源ZIP超过2GB限制");if(size>0&&space.free()<size+HEADROOM)throw new IOException("读取资源包所需空间不足：至少 "+mb(size+HEADROOM)+" MB，当前 "+mb(space.free())+" MB");File zip=File.createTempFile("resource-",".zip",cache);boolean keep=false;try{copy(context.getContentResolver().openInputStream(uri),zip,MAX_ZIP,ticket,"reading",0,size);Plan p=inspectFile(zip,true,ticket);keep=true;return p;}finally{if(!keep)zip.delete();}
 }
 private void ready(Plan p)throws Exception{synchronized(this){current(p.ticket);prepared=p;status=p.review.toString();}}
